function OverseaChatDialoguePanel:StopCo()
    self.frozen = false
    if self.co then
        self.controller:StopCoroutine(self.co)
    end
    self.co = nil
    self.crossWorldCD = false
    if self.crossWorldCo then
        self.controller:StopCoroutine(self.crossWorldCo)
    end
end
function OverseaChatDialoguePanel:ChatLockCoroutine()
    self.frozen = true
    self.co = self.controller:StartCoroutine(util.cs_generator(function()
        coroutine.yield(Yielders.GetWaitForSeconds(ChatConstants.SendMsgFrozenTime))
        self.frozen = false
    end))
end

function OverseaChatDialoguePanel:CrossWorldChatLockCoroutine()
    self.crossWorldCD = true
    self.crossWorldCo = self.controller:StartCoroutine(util.cs_generator(function()
        local social = AppService:GetInstance():GetSocialLine()
        local cd = checkInt(social:GetParamsVoValue(ChatConstants.ChatParams.CROSS_WORLD_INTERVAL))
        coroutine.yield(Yielders.GetWaitForSeconds(cd))
        self.crossWorldCD = false
    end))
end

function OverseaChatDialoguePanel:Awake()
    ---@type PlayerComponent
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComp then
        self.playerId = checkNumber(playerComp.playerDojo.playerId)
    end
    local selfRectTransform = self.Emoji:GetComponent(_RectTransform)
    self._cacheRectTrans = selfRectTransform
    self.allEmoji = CfUtils.GetWholeVo(AutoIds.IdSetting2768, "GoodsEmojiVo")
    self.friendNameTrans = self.Content.transform:Find("FriendNameRoot/FriendName")
    SetButtonAction(self.BtnEmoji, Bind(self, self.ShowEmojiPanel))
    self.private_handler = Events.AddListener(tostring(ChatConstants.Packets.Send_Private_Msg), Bind(self, self.OnPrivateMessageReceive))
    self._receiveGroupChatMsgEvent = Events.AddListener(ChatConstants.EventNames.NEW_GROUP_CHAT_MESSAGE, Bind(self, self.ReceiveGroupChatMsgEventHandler))
    if self.friendNameTrans then
        SetButtonAction(self.friendNameTrans:Find("BtnClose"), function()
            ---@type OverseaChatMainDialog
            local env = self.env
            if env._selectedIndex > #env.data then
                local position = env._selectedIndex - #env.data
                local data = env.privateChat[position]
                if data then
                    local social = AppService:GetInstance():GetSocialLine()
                    social:RemoveRecentContacts(data.friendId)
                    self.env:RefreshPrivateData(data, true)
                end
            end
        end)
    end
    SetButtonAction(self.BtnSend, function()
        if self:GetChannel() == ChatConstants.Channels.Union then
            ---@type ClubComponent
            local clubComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ClubComponent)
            if not clubComponent:IsJoinClub() then
                GameUtils.Toast(localize("不在社团中"))
                return 
            end
        end
        if self:GetChannel() == ChatConstants.Channels.World then
            local social = AppService:GetInstance():GetSocialLine()
            local levelLimit = social:GetParamsVoValue(ChatConstants.ChatParams.WORLD_OPEN_LEVEL)
            local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            if not playerComp:IsOpenByLevel(levelLimit) then
                GameUtils.Toast(localize("调查官_num_级开启世界频道发言功能。", {_num_ = levelLimit}))
                return
            end
        elseif self:GetChannel() == ChatConstants.Channels.CrossWorld then
            local social = AppService:GetInstance():GetSocialLine()
            local questId = social:GetParamsVoValue(ChatConstants.ChatParams.CROSS_WORLD_OPEN_LEVEL)
            local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(questId)
            if not isUnlock then
                GameUtils.Toast(GameUtils.GetUnlockDescr(Constants.CommonUnlockType.PassQuest, checkString(questId)))
                return
            end
        end

        if self:GetChannel() == ChatConstants.Channels.CrossWorld then
            if self.crossWorldCD then
                local social = AppService:GetInstance():GetSocialLine()
                local cd = checkInt(social:GetParamsVoValue(ChatConstants.ChatParams.CROSS_WORLD_INTERVAL))
                GameUtils.Toast(localize('冷却时间_num_秒未结束，不能再发送', { _num_ = cd }))
                return
            end
        else
            if self.frozen then
                GameUtils.Toast(localize('冷却时间_num_秒未结束，不能再发送', { _num_ = ChatConstants.SendMsgFrozenTime }))
                return
            end
        end

        local text = self.InputField.text
        if not string.isEmpty(text) then
            -- 字数限制
            if CfUtils.GetCustomStringLen(text) > CHAT_LENGTH_LIMIT then
                GameUtils.Toast(localize("单次发言不能超过50个汉字"))
                return
            end
            
            if self:GetChannel() == ChatConstants.Channels.CrossWorld then
                self:CrossWorldChatLockCoroutine()
            else
                self:ChatLockCoroutine()
            end
            ---开启冷却时间
            ---发送聊天消息,TODO 冷却时间
            local social = AppService:GetInstance():GetSocialLine()
            social:SendTcpData(self:GetTcpPacket(), self:GetTcpParams(string.trim(text), ChatConstants.ChatMsgType.TEXT))

            -- 提示 RefreshWorldListView() 是玩家自己发的信息
            if self:IsChannelWhichNeedShowBtnNew() then 
                self.isMsgSendFromSelf = true
            end
        end
    end) 


    ---
    SetButtonAction(self.BtnNew, function()
        if isNotNull(self.ScrollView) and ( isNotNull(self.data) and #self.data > 0 ) then 
            self.ScrollView:MovePanelToItemIndex(#self.data - 1)  -- 0 based  
        else 
            printError("异常, 按钮未起效, 请检测代码")
        end 
        CfUtils.SetActive( self.BtnNew, false )
    end)
    CfUtils.SetActive( self.BtnNew, false )

end


---OnPrivateMessageReceive
---接收私信息消息
---@param data table
function OverseaChatDialoguePanel:OnPrivateMessageReceive(data)
    print('--->>', table.dump(data, false, 2))
    if data.req and data.req.msgType then
        local msgType = checkNumber(data.req.msgType)
        if msgType == ChatConstants.ChatMsgType.TEXT then
            self.InputField.text = "" ---重置空数据
            --2.更新列表数据
        elseif msgType == ChatConstants.ChatMsgType.EMOJI then
        end
    end
    
    local channel = self:GetChannel()
    if channel == ChatConstants.Channels.Single then
        if data.resp and data.resp[1] then
            if checkInt(data.resp[1].friendId) == checkInt(self.friendId) then
                local social = AppService:GetInstance():GetSocialLine()
                social:ReadUnreadMessage(self.friendId)
            end
        end
        self:FreshPrivateListView()
    end
end

---接收到新的群聊信息处理
---@param data table
function OverseaChatDialoguePanel:ReceiveGroupChatMsgEventHandler(data)
    local social = AppService:GetInstance():GetSocialLine()
    local serverChannel = checkNumber(data.chatChannel)
    local chatChannel = social:ServerChannelToChannel(serverChannel)
    if chatChannel ~= self:GetChannel() then
        return
    end

    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if checkInt(data.playerId) == checkNumber(playerComp.playerDojo.playerId) then
        self.InputField.text = "" ---重置空数据
    end

    
    if chatChannel == ChatConstants.Channels.Fight then
        self:RefreshTeamListView()
        social:UnmarkNewMessage(ChatConstants.ChatServerChannel.Fight)
    elseif checkNumber(chatChannel) == ChatConstants.Channels.Union then
        ---工会聊天信息
        self:RefreshClubListView()
        social:UnmarkNewMessage(ChatConstants.ChatServerChannel.Union)
    elseif checkNumber(chatChannel) == ChatConstants.Channels.World then

        --printError("世界 新消息")
        self:RefreshWorldListView( false )

        social:UnmarkNewMessage(ChatConstants.ChatServerChannel.World)
    elseif checkNumber(chatChannel) == ChatConstants.Channels.CrossWorld then
        self:RefreshCrossWorldListView()
        social:UnmarkNewMessage(ChatConstants.ChatServerChannel.CrossWorld)
    end
end

