function OverseaChatDialoguePanel:ShowEmojiPanel()
    self.emojiOpen = not self.emojiOpen
    --KTool.SetActive(self.Emoji, self.emojiOpen)
    if self.emojiOpen then
        self.pageMax = math.floor((#self.allEmoji + ChatConstants.EmojiPageSize - 1) / ChatConstants.EmojiPageSize)
        self.dots = {}
        KTool.DestroyGameObjectChildren(self.PageGroup.gameObject, false)
        for _ = 1, self.pageMax do
            local go = KTool.Instantiate(self.PageGroup.gameObject, self.ImgPoint.gameObject, false)
            KTool.SetActive(go, true)
            table.insert(self.dots, go)
        end
        self:UpdateDots()
        ---表情包的界面的刷新的逻辑
        if not self.PageView.IsListViewInit then
            local initParam = CS.SuperScrollView.LoopListViewInitParam.CopyDefaultInitParam()
            initParam.mSnapVecThreshold = 99999
            --self.PageView.mOnBeginDragAction = OnBeginDrag
            --self.PageView.mOnDragingAction = OnDraging
            self.PageView.mOnEndDragAction = Bind(self, self.OnEndDrag)
            self.PageView.mOnSnapNearestChanged = Bind(self, self.OnSnapNearestChanged)
            self.PageView:InitListView(self.pageMax, Bind(self, self.OnGetEmojiItemByIndex), initParam)
        else
            GameUtils.ReloadData(self.PageView, self.pageMax)
        end
        self:PlayShowEmojiAnimation()
    else
        self:PlayHideEmojiAnimation()
    end
end

function OverseaChatDialoguePanel:OnEndDrag()
    local vec = self.PageView.ScrollRect.velocity.x
    local curNearestItemIndex = self.PageView.CurSnapNearestItemIndex
    local item = self.PageView:GetShownItemByItemIndex(curNearestItemIndex)
    if isNull(item) then
        self.PageView:ClearSnapData()
        return
    end
    if Mathf.Abs(vec) < 50 then
        self.PageView:SetSnapTargetItemIndex(curNearestItemIndex)
        return
    end
    local pos = self.PageView:GetItemCornerPosInViewPort(item, CS.SuperScrollView.ItemCornerEnum.LeftTop)
    if pos.x > 0 then
        if vec > 0 then
            self.PageView:SetSnapTargetItemIndex(curNearestItemIndex - 1)
        else
            self.PageView:SetSnapTargetItemIndex(curNearestItemIndex)
        end
    elseif pos.x < 0 then
        if vec > 0 then
            self.PageView:SetSnapTargetItemIndex(curNearestItemIndex)
        else
            self.PageView:SetSnapTargetItemIndex(curNearestItemIndex + 1)
        end
    else
        if vec > 0 then
            self.PageView:SetSnapTargetItemIndex(curNearestItemIndex - 1)
        else
            self.PageView:SetSnapTargetItemIndex(curNearestItemIndex + 1)
        end
    end
end

function OverseaChatDialoguePanel:UpdateDots()
    local curNearestItemIndex = self.PageView.CurSnapNearestItemIndex
    if curNearestItemIndex < 0 or curNearestItemIndex > self.pageMax then
        return
    end
    if curNearestItemIndex > #self.dots then
        return
    end
    for i = 1, #self.dots do
        local go = self.dots[i]
        if i == (curNearestItemIndex + 1) then
            CfUtils.SetUISwitchImage(go, 1)
        else
            CfUtils.SetUISwitchImage(go, 2)
        end
    end
end

function OverseaChatDialoguePanel:OnSnapNearestChanged(listView, item)
    ---update dots
    self:UpdateDots()
end

function OverseaChatDialoguePanel:OnGetEmojiItemByIndex(listView, index, item)
    if index < 0 then
        return nil
    end
    local pageNo = index + 1
    print('---->>', pageNo)
    local count = math.min(ChatConstants.EmojiPageSize, math.abs(#self.allEmoji - ChatConstants.EmojiPageSize * index))
    local cell = listView:NewListViewItem("PageCell")
    ---@type OverseaChatEmojiCell
    local env = CfUtils.GetLuaScr(cell.gameObject, OverseaChatEmojiCell)
    if env then
        env:FreshUI(self.allEmoji, pageNo, count, ChatConstants.EmojiPageSize, Bind(self, self.OnClickEmoji))
    end
    return cell
end
---OnClickEmoji
---表情的点击位置
---@param position number @具体位置
---@param vo GoodsEmojiVo @具体表情类型
function OverseaChatDialoguePanel:OnClickEmoji(position, vo)
    if self:GetChannel() == ChatConstants.Channels.World or self:GetChannel() == ChatConstants.Channels.CrossWorld then
        local social = AppService:GetInstance():GetSocialLine()
        local levelLimit = social:GetParamsVoValue(ChatConstants.ChatParams.WORLD_OPEN_LEVEL)
        local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if not playerComp:IsOpenByLevel(levelLimit) then
            GameUtils.Toast(localize("调查官_num_级开启世界频道发言功能。", {_num_ = levelLimit}))
            return
        end
    end
    --发送聊天表情, 发送成功能记录数据库
    if self:GetChannel() == ChatConstants.Channels.CrossWorld then
        if self.crossWorldCD then
            local social = AppService:GetInstance():GetSocialLine()
            local cd = checkInt(social:GetParamsVoValue(ChatConstants.ChatParams.CROSS_WORLD_INTERVAL))
            GameUtils.Toast(localize('冷却时间_num_秒未结束，不能再发送', { _num_ = cd }))
            return
        end
    else
        if self.frozen then
            GameUtils.Toast(localize('冷却时间_num_秒未结束，不能再发送', { _num_ = ChatConstants.SendMsgFrozenTime }))
            return
        end
    end

    if self:GetChannel() == ChatConstants.Channels.CrossWorld then
        self:CrossWorldChatLockCoroutine()
    else
        self:ChatLockCoroutine()
    end
    ---开启冷却时间
    local social = AppService:GetInstance():GetSocialLine()
    social:SendTcpData(self:GetTcpPacket(), self:GetTcpParams(string.format("#[%d]#", vo.id), ChatConstants.ChatMsgType.EMOJI))
    -- 关闭表情页面
    self.emojiOpen = false
    self:PlayHideEmojiAnimation()

    -- 标记玩家自己发的 emoji
    if self:IsChannelWhichNeedShowBtnNew() == true then 
        self.isEmojiSendFromSelf = true
    end
end

