---Refresh  切换页签时触发:
---@param env OverseaChatMainDialog
function OverseaChatDialoguePanel:Refresh(env, isClick)
    self.env = env

    if isClick then
        self:ResetEmojiPanel()
    end

    
    -- 是否是启用了 "新消息下拉按钮" 功能的channel:
    local isNeedShowBtnNew = self:IsChannelWhichNeedShowBtnNew()
    
    if self.friendNameTrans then
        KTool.SetActive(self.friendNameTrans.gameObject, env._selectedIndex > #env.data)
    end
    if env._selectedIndex > #env.data then
        ----私聊页签时
        ---@type UnityEngine.RectTransform
        local rectTrans = self.ScrollView:GetComponent("RectTransform")
        local height = rectTrans.sizeDelta.y
        local posY = -469
        if env._selectedIndex > #env.data then
            posY = -504
            height = height - 100
            local position = env._selectedIndex - #env.data
            local data = env.privateChat[position]
            self.friendId = checkNumber(data.friendId)
            self.friendData = data
            ---私信好友信息状态
            if self.friendNameTrans then
                CfUtils.FillText(self.friendNameTrans:Find("TextName"), data.name)
                if isClick then
                    self:PlayShowNameAnimation()
                end
            end
            self:FreshPrivateListView()
        end
    elseif self:GetChannel() == ChatConstants.Channels.Fight then
        -- 队伍聊天
        self:RefreshTeamListView()
        if isClick then
            self:PlayHideNameAnimation()
        end
    elseif self:GetChannel() == ChatConstants.Channels.Union then
        self:RefreshClubListView()
        if isClick then
            self:PlayHideNameAnimation()
        end
    elseif self:GetChannel() == ChatConstants.Channels.World then

        if isClick then
            self.ScrollView.mOnEndDragAction = Bind(self, self.OnEndDragWorld)
            self:RefreshWorldListView( true )
            self:PlayHideNameAnimation()
        end

    elseif self:GetChannel() == ChatConstants.Channels.CrossWorld then
        self:RefreshCrossWorldListView()
        if isClick then
            self:PlayHideNameAnimation()
        end
    else
        ---其他页签，战斗or招募
        if isClick then
            self:PlayHideNameAnimation()
        end
        GameUtils.ReloadData(self.ScrollView, 0)
    end

    -- 别的channel 要隐藏此按钮
    if isNeedShowBtnNew ~= true then 
        CfUtils.SetActive( self.BtnNew, false )
    end 

    --rectTrans.anchoredPosition = Vector2.New(rectTrans.anchoredPosition.x, posY)
    --rectTrans.sizeDelta = Vector2.New(rectTrans.sizeDelta.x, height)
end


---@return boolean 
function OverseaChatDialoguePanel:IsChannelWhichNeedShowBtnNew()
    return (self:GetChannel() == ChatConstants.Channels.World)
end


function OverseaChatDialoguePanel:ResetEmojiPanel()
    CfUtils.SetActive(self.Emoji, false)
    self.emojiOpen = false
    local viewport = self.ScrollView.transform:Find("Viewport")
    if isNotNull(viewport) then
        viewport.transform.anchoredPosition = Vector2.zero
    end
    self._channel = self:GetChannel()
end

function OverseaChatDialoguePanel:FreshPrivateListView()
    local social = AppService:GetInstance():GetSocialLine()
    ---@type PlayerComponent
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if isNull(playerComp) then
        return
    end
    self.data = self:ConvertDataWithTime(social:GetPrivateChatMsg(playerComp.playerDojo.playerId, checkNumber(self.friendId)))
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitListView(#self.data, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #self.data)
    end
    if #self.data > 0 then
        self.ScrollView:MovePanelToItemIndex(#self.data - 1)
    end
end

---刷新队伍聊天
