---@param isFormPanelChange_ boolean @ 是因为切换 channel 导致的本函数调用吗?
function OverseaChatDialoguePanel:RefreshWorldListView( isFormPanelChange_ )

    local social = AppService:GetInstance():GetSocialLine()
    self.data = self:ConvertDataWithTime(social.worldData)
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitListView(#self.data, Bind(self, self.OnGetItemByIndex)) -- 因为入场时默认不指向 world 页签, 故此句不会被执行到
    else
        GameUtils.ReloadData_Repaired(self.ScrollView, #self.data, false ) -- 重装填, 但不将 idx 重置到头部
    end
    if #self.data == 0 then 
        return
    end 
    --- 仅当: (1)当前正在支持 btnNew 的面板, (2)列表中不显示最后一行信息; (3)收到了别人发的新消息; 才需要显示 btnNew 按钮;

    local lastItem = self.ScrollView:GetShownItemByItemIndex(#self.data - 1)
    local canSeeLastItem = isNotNull(lastItem)
     

    local isNeedShowBtnNew = (isFormPanelChange_ == false and (canSeeLastItem == false) and self.isMsgSendFromSelf == false and self.isEmojiSendFromSelf == false ) -- !!! todo    
    self.isMsgSendFromSelf = false -- 一次性的, 无论如何都要清空
    self.isEmojiSendFromSelf = false

    ---
    if isNeedShowBtnNew == true then 
        CfUtils.SetActive( self.BtnNew, true ) 
    else 
        self.ScrollView:MovePanelToItemIndex(#self.data - 1)
        CfUtils.SetActive( self.BtnNew, false ) 
    end 
end



function OverseaChatDialoguePanel:OnEndDragWorld()
    if isNull(self.data) or #self.data == 0 then 
        return
    end 
    -- 滚动到底后主动隐藏 新消息按钮:
    local lastItem = self.ScrollView:GetShownItemByItemIndex(#self.data - 1)
    if isNotNull(lastItem) then 
        CfUtils.SetActive( self.BtnNew, false )
    end 
end



function OverseaChatDialoguePanel:RefreshCrossWorldListView()
    local social = AppService:GetInstance():GetSocialLine()
    self.data = self:ConvertDataWithTime(social.crossWorldData)
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitListView(#self.data, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #self.data)
    end
    if #self.data > 0 then
        self.ScrollView:MovePanelToItemIndex(#self.data - 1)
    end
end

function OverseaChatDialoguePanel:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local prefabName = PrefabMyName
    local position = index + 1
    local data = self.data[position]
    if data.timestamp then
        local cell = listView:NewListViewItem(TimeCell)
        local text = cell.transform:Find('TextNumber')
        local timeStr = self:GetTimeString(data.timestamp)
        CfUtils.FillText(text, timeStr)
        return cell
    end
    
    if self:GetChannel() == ChatConstants.Channels.Single then
        if checkInt(data.sendPlayerId) == checkInt(self.playerId) then
            ---表示是我发送的
            prefabName = PrefabMyName
        else
            ---好友发送的
            prefabName = PrefabOtherName
        end
    elseif self:GetChannel() == ChatConstants.Channels.Fight or 
        self:GetChannel() == ChatConstants.Channels.Union or 
        self:GetChannel() == ChatConstants.Channels.World or
        self:GetChannel() == ChatConstants.Channels.CrossWorld then
        if checkInt(data.playerId) == checkInt(self.playerId) then
            ---表示是我发送的
            prefabName = PrefabMyName
        else
            ---好友发送的
            prefabName = PrefabOtherName
        end
    end

    local cell = listView:NewListViewItem(prefabName)
    ---@type OverseaChatMessageCell
    local env = CfUtils.GetLuaScr(cell, OverseaChatMessageCellPath)
    if env then
        --print('--->>', self:GetChannel())
        if self:GetChannel() == ChatConstants.Channels.Fight or
            self:GetChannel() == ChatConstants.Channels.Union or
            self:GetChannel() == ChatConstants.Channels.World or
            self:GetChannel() == ChatConstants.Channels.CrossWorld then
            local copy = data
            copy.content = copy.message
            copy.sendPlayerId = copy.playerId   
            env:FreshUI(copy, self.playerId, copy.name, copy)
        else
            env:FreshUI(data, self.playerId, self.friendData.name, self.friendData)
        end
    end

    return cell
end

function OverseaChatDialoguePanel:MeasureSize(content)
    local contentTrans = self.Content.transform.parent:Find("NotDelete")
    local descTextTrans = contentTrans:Find("Dialogue/TextDesc")
    KTool.SetActive(descTextTrans.gameObject, false)
    KTool.SetActive(descTextTrans.gameObject, true)
    CfUtils.FillText(descTextTrans, content)

    -----@type UnityEngine.UI.ContentSizeFitter
    local contentSizeFitter = KTool.GetComponent(descTextTrans.gameObject, typeof(CS.UnityEngine.UI.ContentSizeFitter))
    contentSizeFitter:SetLayoutVertical()
    ---@type UnityEngine.RectTransform
    local sizeTrans = KTool.GetComponent(descTextTrans.gameObject, typeof(CS.UnityEngine.RectTransform))
    print('--->>xxx', sizeTrans.sizeDelta, content)
    return sizeTrans.sizeDelta
end

---获取当前选中频道id
function OverseaChatDialoguePanel:GetChannel()
    if isNull(self.env) then
        return
    end

    if self.env._selectedIndex > #self.env.data then
        return ChatConstants.Channels.Single
    else
        return self.env.data[self.env._selectedIndex].id
    end
end

function OverseaChatDialoguePanel:GetTcpPacket()
    if self:GetChannel() == ChatConstants.Channels.Single then
        return ChatConstants.Packets.Send_Private_Msg
    elseif self:GetChannel() == ChatConstants.Channels.Fight or 
        self:GetChannel() == ChatConstants.Channels.Union or 
        self:GetChannel() == ChatConstants.Channels.World or 
        self:GetChannel() == ChatConstants.Channels.CrossWorld then
        return ChatConstants.Packets.Send_Group_Chat_Msg
    else
        return ChatConstants.Packets.Send_Private_Msg
    end
end

function OverseaChatDialoguePanel:GetTcpParams(message, msgType)
    if self:GetChannel() == ChatConstants.Channels.Single then
        return {
            friendId = self.friendId,
            message = message,
            msgType = msgType,
        }
    elseif self:GetChannel() == ChatConstants.Channels.Fight then
        local social = AppService:GetInstance():GetSocialLine()
        return {
            msgType = msgType,
            chatChannel = ChatConstants.ChatServerChannel.Fight,
            message = message,
            roomId = social.teamRoomId
        }
    elseif self:GetChannel() == ChatConstants.Channels.Union then
        local social = AppService:GetInstance():GetSocialLine()
        return {
            msgType = msgType,
            chatChannel = ChatConstants.ChatServerChannel.Union,
            chatType = ChatConstants.Channels.Union,
            message = message,
            roomId = social.clubRoomId
        }
    elseif self:GetChannel() == ChatConstants.Channels.World then
        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        local serverId = 0
        local areaId  = 0
        if userComponent then
            serverId = checkNumber(userComponent.userInfo.serverId)
            local serverDojo = userComponent:GetServerById(HttpModule.RequestBodyMeta.serverId)  
            areaId = checkInt(serverDojo.areaId)
        end
        
        return {
            msgType = msgType,
            chatChannel = ChatConstants.ChatServerChannel.World,
            chatType = ChatConstants.Channels.World,
            message = message,
            roomId = areaId,
        }
    elseif self:GetChannel() == ChatConstants.Channels.CrossWorld then
        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        local serverId = 0
        local areaId  = 0
        if userComponent then
            serverId = checkNumber(userComponent.userInfo.serverId)
            local serverDojo = userComponent:GetServerById(HttpModule.RequestBodyMeta.serverId)  
            areaId = checkInt(serverDojo.areaId)
        end
        
        return {
            msgType = msgType,
            chatChannel = ChatConstants.ChatServerChannel.CrossWorld,
            chatType = ChatConstants.Channels.CrossWorld,
            message = message,
            roomId = areaId,
        }
    end
end

function OverseaChatDialoguePanel:PlayShowNameAnimation()
    CfUtils.PlayAnimation(self.ViewportAni, AnimationNameConfig.SHOW_NAME)
end

function OverseaChatDialoguePanel:PlayHideNameAnimation()
    CfUtils.PlayAnimation(self.ViewportAni, AnimationNameConfig.HIDE_NAME)
end

function OverseaChatDialoguePanel:PlayShowEmojiAnimation()
    self:StopAniCo()
    KTool.SetActive(self.Emoji, true)
    CfUtils.PlayAnimation(self.ViewportAni, AnimationNameConfig.SHOW_EMOJI)
    CfUtils.PlayAnimation(self.EmojiRoot, AnimationNameConfig.SHOW_EMOJI_ROOT)
end

function OverseaChatDialoguePanel:PlayHideEmojiAnimation()
    CfUtils.PlayAnimation(self.ViewportAni, AnimationNameConfig.HIDE_EMOJI)
    CfUtils.PlayAnimation(self.EmojiRoot, AnimationNameConfig.HIDE_EMOJI_ROOT)
    self:StopAniCo()
    self._aniCo = cs_coroutine.start(function()
        coroutine.yield(Yielders.GetWaitForSeconds(0.18))
        KTool.SetActive(self.Emoji, false)
    end)
end

function OverseaChatDialoguePanel:StopAniCo()
    if not isNull(self._aniCo) then
        cs_coroutine.stop(self._aniCo)
        self._aniCo = nil
    end
end

function OverseaChatDialoguePanel:ConvertDataWithTime(data)
    local tmp = {}
    local time = 0
    for i, v in ipairs(checkTable(data)) do
        local sendTime = checkInt(v.sendTime)
        if sendTime - time > 300 then
            time = sendTime
            table.insert(tmp, {timestamp = sendTime})
        end
        table.insert(tmp, v)
    end
    return tmp
end

function OverseaChatDialoguePanel:GetTimeString(timestamp)
    local time = checkInt(timestamp)
    local day = os.date("%Y/%m/%d", time)
    local today = os.date("%Y/%m/%d", os.time())
    if day == today then
        return os.date("%H:%M:%S", time)
    else
        return os.date("%Y/%m/%d %H:%M:%S", time)
    end
end

----
---添加空白关闭
----
function OverseaChatDialoguePanel:OnEnable()
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function()
            self:Update()
        end
        self._behaviourAction = behaviourAction
    end
end

function OverseaChatDialoguePanel:OnDisable()
    if self._behaviourAction then
        self._behaviourAction.UpdateAction = nil
        self._behaviourAction = nil
    end
end

function OverseaChatDialoguePanel:Update()
    if Utils.TouchCount() > 0 and self.emojiOpen then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self._cacheRectTrans, position,
                    UIModule.RootCanvas.canvas.worldCamera) or 
                    RectTransformUtility.RectangleContainsScreenPoint(self.BtnEmoji, position,
                    UIModule.RootCanvas.canvas.worldCamera)
            if not isInRect then
                ---不在区域中
                self.emojiOpen = false
                --KTool.SetActive(self.Emoji.gameObject, false)
                self:PlayHideEmojiAnimation()
            end
        end
    end
end

function OverseaChatDialoguePanel:OnDestroy()
    Events.RemoveListener(tostring(ChatConstants.Packets.Send_Private_Msg), self.private_handler)
    Events.RemoveListener(tostring(ChatConstants.EventNames.NEW_GROUP_CHAT_MESSAGE), self._receiveGroupChatMsgEvent)
    self.private_handler = nil
    self:StopCo()
    self:StopAniCo()
    self.env = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return OverseaChatDialoguePanel